        launch(args);
    }
}

package com.auction.main;

import com.auction.database.DatabaseInitializer;
import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class App extends Application {

    @Override
    public void start(Stage stage) throws Exception {
        DatabaseInitializer.initDatabase();  // Khởi tạo database tự động

        FXMLLoader fxmlLoader = new FXMLLoader(getClass().getResource("/fxml/Login.fxml"));
        Parent root = fxmlLoader.load();

        Scene scene = new Scene(root, 1024, 720);
        stage.setTitle("Hệ Thống Đấu Giá Biển Số - VinGroup");
        stage.setScene(scene);
        stage.setResizable(false);
        stage.centerOnScreen();
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package com.auction.database;

import java.sql.*;

/**
 * AuctionDAO - Quản lý phiên đấu giá (auctions)
 */
public class AuctionDAO {

    // Tạo phiên đấu giá mới
    public static void createAuction(int itemId, int sellerId) {
        String sql = "INSERT INTO auctions (item_id, seller_id, is_open) VALUES (?, ?, TRUE)";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, itemId);
            pstmt.setInt(2, sellerId);

            pstmt.executeUpdate();
            System.out.println("✅ Tạo phiên đấu giá thành công");

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Lấy tất cả phiên đấu giá đang mở
    public static void getOpenAuctions() {
        String sql = "SELECT a.id, i.plate_number, i.current_price, u.full_name " +
                     "FROM auctions a " +
                     "JOIN items i ON a.item_id = i.id " +
                     "JOIN users u ON a.seller_id = u.id " +
                     "WHERE a.is_open = TRUE";

        try (Connection conn = DatabaseConnection.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            System.out.println("\n Phiên đấu giá đang mở:");
            while (rs.next()) {
                System.out.println("  Phiên #" + rs.getInt("id") + 
                                 " | Biển: " + rs.getString("plate_number") +
                                 " | Giá: " + rs.getDouble("current_price") +
                                 " | Seller: " + rs.getString("full_name"));
            }
            System.out.println();

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Đóng phiên đấu giá (khi hết giờ)
    public static void closeAuction(int auctionId, int winnerId, double finalPrice) {
        String sql = "UPDATE auctions SET is_open = FALSE, winner_id = ?, final_price = ? WHERE id = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, winnerId);
            pstmt.setDouble(2, finalPrice);
            pstmt.setInt(3, auctionId);

            pstmt.executeUpdate();
            System.out.println("✅ Đóng phiên đấu giá thành công");

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Lấy chi tiết phiên đấu giá
    public static void getAuctionDetails(int auctionId) {
        String sql = "SELECT a.*, i.plate_number, u.full_name FROM auctions a " +
                     "JOIN items i ON a.item_id = i.id " +
                     "JOIN users u ON a.seller_id = u.id " +
                     "WHERE a.id = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, auctionId);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                System.out.println("\n Chi tiết phiên:");
                System.out.println("  Phiên #: " + rs.getInt("id"));
                System.out.println("  Biển: " + rs.getString("plate_number"));
                System.out.println("  Người bán: " + rs.getString("full_name"));
                System.out.println("  Giá hiện tại: " + rs.getDouble("final_price"));
                System.out.println("  Trạng thái: " + (rs.getBoolean("is_open") ? "Đang mở" : "Đã đóng") + "\n");
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }
}

package com.auction.database;

import java.sql.*;

/**
 * BidDAO - Quản lý lịch sử đặt giá (bids)
 */
public class BidDAO {

    // Thêm bid mới
    public static void addBid(int auctionId, int bidderId, double amount) {
        String sql = "INSERT INTO bids (auction_id, bidder_id, amount) VALUES (?, ?, ?)";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, auctionId);
            pstmt.setInt(2, bidderId);
            pstmt.setDouble(3, amount);

            pstmt.executeUpdate();
            System.out.println("✅ Đặt giá " + amount + " thành công");

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Lấy tất cả bids của 1 phiên (sắp xếp từ cao xuống thấp)
    public static void getBidsForAuction(int auctionId) {
        String sql = "SELECT b.id, u.full_name, b.amount, b.bid_time " +
                     "FROM bids b " +
                     "JOIN users u ON b.bidder_id = u.id " +
                     "WHERE b.auction_id = ? " +
                     "ORDER BY b.amount DESC";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, auctionId);
            ResultSet rs = pstmt.executeQuery();

            System.out.println("\n Lịch sử đặt giá (Phiên #" + auctionId + "):");
            while (rs.next()) {
                System.out.println("  " + rs.getString("full_name") + 
                                 " - " + rs.getDouble("amount") + 
                                 " đ (" + rs.getTimestamp("bid_time") + ")");
            }
            System.out.println();

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Lấy giá cao nhất của phiên
    public static double getHighestBidForAuction(int auctionId) {
        String sql = "SELECT MAX(amount) AS highest FROM bids WHERE auction_id = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, auctionId);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                return rs.getDouble("highest");
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }

        return 0;
    }


    // Lấy người đặt giá cao nhất
    public static void getHighestBidder(int auctionId) {
        String sql = "SELECT u.full_name, b.amount " +
                     "FROM bids b " +
                     "JOIN users u ON b.bidder_id = u.id " +
                     "WHERE b.auction_id = ? " +
                     "ORDER BY b.amount DESC LIMIT 1";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, auctionId);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                System.out.println(" Người đặt giá cao nhất: " + rs.getString("full_name") + 
                                 " (" + rs.getDouble("amount") + " đ)");
            } else {
                System.out.println("Chưa có ai đặt giá");
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Đếm số lần đặt giá trong phiên
    public static void countBidsForAuction(int auctionId) {
        String sql = "SELECT COUNT(*) AS bid_count FROM bids WHERE auction_id = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, auctionId);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                System.out.println(" Tổng lần đặt giá: " + rs.getInt("bid_count"));
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }
}

package com.auction.database;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

/**
 * Kết nối MySQL - File này càng đơn giản càng tốt
 * 
 * Các bạn chỉ cần:
 * 1. Thay PASSWORD thành mật khẩu MySQL của mình
 * 2. Chạy DatabaseInitializer.initDatabase() 1 lần khi app start
 * 3. Xong! Dùng UserDAO, ItemDAO, v.v. để query
 */
public class DatabaseConnection {

    // === CÁC BẠN ĐỔI ĐỦ ĐIỀU NÀY ===
    private static final String URL = "jdbc:mysql://localhost:3306/auction_db";
    private static final String USER = "root";
    private static final String PASSWORD = "123456";  // <- ĐỔI TẠI ĐÂY theo mật khẩu MySQL của bạn


    public static Connection getConnection() throws SQLException {
        return DriverManager.getConnection(URL, USER, PASSWORD);
    }


    // Gọi hàm này để test: DatabaseConnection.testConnection()
    public static void testConnection() {
        try (Connection conn = getConnection()) {
            System.out.println("✅ Kết nối MySQL thành công!");
        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }
}

package com.auction.database;

import java.sql.Connection;
import java.sql.Statement;
import java.sql.SQLException;

/**
 * Tự động tạo các bảng khi app khởi động
 * 
 * Giải thích:
 * - DatabaseInitializer.initDatabase() chạy 1 lần
 * - Nó tạo 4 bảng: users, items, auctions, bids
 * - Nếu bảng đã tồn tại → bỏ qua
 * - Nếu bảng chưa tồn tại → tạo mới
 */
public class DatabaseInitializer {

    public static void initDatabase() {
        try (Connection conn = DatabaseConnection.getConnection();
             Statement stmt = conn.createStatement()) {

            // === BẢNG 1: USERS - Lưu người dùng (buyer, seller) ===
            String createUsers = "CREATE TABLE IF NOT EXISTS users (" +
                    "  id INT PRIMARY KEY AUTO_INCREMENT," +
                    "  username VARCHAR(50) NOT NULL UNIQUE," +
                    "  password VARCHAR(255) NOT NULL," +
                    "  email VARCHAR(100)," +
                    "  full_name VARCHAR(100)," +
                    "  user_type VARCHAR(20)," +
                    "  phone VARCHAR(15)," +
                    "  address TEXT," +
                    "  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP" +
                    ")";
            stmt.execute(createUsers);
            System.out.println("✅ Bảng users sẵn sàng");


            // === BẢNG 2: ITEMS - Lưu biển số xe (đồ đấu giá) ===
            String createItems = "CREATE TABLE IF NOT EXISTS items (" +
                    "  id INT PRIMARY KEY AUTO_INCREMENT," +
                    "  plate_number VARCHAR(20) NOT NULL UNIQUE," +
                    "  start_price DECIMAL(15,2)," +
                    "  current_price DECIMAL(15,2)," +
                    "  description TEXT," +
                    "  vehicle_type VARCHAR(50)," +
                    "  status VARCHAR(20)" +
                    ")";
            stmt.execute(createItems);
            System.out.println("✅ Bảng items sẵn sàng");


            // === BẢNG 3: AUCTIONS - Lưu phiên đấu giá ===
            String createAuctions = "CREATE TABLE IF NOT EXISTS auctions (" +
                    "  id INT PRIMARY KEY AUTO_INCREMENT," +
                    "  item_id INT NOT NULL," +
                    "  seller_id INT NOT NULL," +
                    "  winner_id INT," +
                    "  is_open BOOLEAN DEFAULT TRUE," +
                    "  start_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP," +
                    "  end_time DATETIME," +
                    "  final_price DECIMAL(15,2)," +
                    "  FOREIGN KEY (item_id) REFERENCES items(id)," +
                    "  FOREIGN KEY (seller_id) REFERENCES users(id)," +
                    "  FOREIGN KEY (winner_id) REFERENCES users(id)" +
                    ")";
            stmt.execute(createAuctions);
            System.out.println("✅ Bảng auctions sẵn sàng");


            // === BẢNG 4: BIDS - Lưu lịch sử đặt giá ===
            String createBids = "CREATE TABLE IF NOT EXISTS bids (" +
                    "  id INT PRIMARY KEY AUTO_INCREMENT," +
                    "  auction_id INT NOT NULL," +
                    "  bidder_id INT NOT NULL," +
                    "  amount DECIMAL(15,2)," +
                    "  bid_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP," +
                    "  FOREIGN KEY (auction_id) REFERENCES auctions(id)," +
                    "  FOREIGN KEY (bidder_id) REFERENCES users(id)" +
                    ")";
            stmt.execute(createBids);
            System.out.println("✅ Bảng bids sẵn sàng");

            System.out.println("\n✅✅✅ Database khởi tạo thành công! ✅✅✅\n");

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }
}

package com.auction.database;

import java.sql.*;

/**
 * ItemDAO - Quản lý biển số xe (items)
 */
public class ItemDAO {

    // Thêm item (biển số xe) mới
    public static void addItem(String plateNumber, double startPrice, String description, 
                               String vehicleType, String status) {
        String sql = "INSERT INTO items (plate_number, start_price, current_price, description, vehicle_type, status) " +
                     "VALUES (?, ?, ?, ?, ?, ?)";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, plateNumber);
            pstmt.setDouble(2, startPrice);
            pstmt.setDouble(3, startPrice);  // current_price = start_price lúc đầu
            pstmt.setString(4, description);
            pstmt.setString(5, vehicleType);
            pstmt.setString(6, status);

            pstmt.executeUpdate();
            System.out.println("✅ Thêm item biển '" + plateNumber + "' thành công");

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Lấy item theo plate_number
    public static void getItemByPlate(String plateNumber) {
        String sql = "SELECT * FROM items WHERE plate_number = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, plateNumber);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                System.out.println("\n Thông tin item:");
                System.out.println("  ID: " + rs.getInt("id"));
                System.out.println("  Biển: " + rs.getString("plate_number"));
                System.out.println("  Giá khởi điểm: " + rs.getDouble("start_price"));
                System.out.println("  Giá hiện tại: " + rs.getDouble("current_price"));
                System.out.println("  Loại xe: " + rs.getString("vehicle_type"));
                System.out.println("  Trạng thái: " + rs.getString("status") + "\n");
            } else {
                System.out.println("❌ Không tìm thấy item");
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Lấy tất cả items
    public static void getAllItems() {
        String sql = "SELECT plate_number, start_price, current_price, vehicle_type, status FROM items";

        try (Connection conn = DatabaseConnection.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            System.out.println("\n Danh sách items:");
            while (rs.next()) {
                System.out.println("  Biển: " + rs.getString("plate_number") + 
                                 " | Giá: " + rs.getDouble("current_price") + 
                                 " | Loại: " + rs.getString("vehicle_type"));
            }
            System.out.println();

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Cập nhật giá hiện tại của item
    public static void updateCurrentPrice(String plateNumber, double newPrice) {
        String sql = "UPDATE items SET current_price = ? WHERE plate_number = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setDouble(1, newPrice);
            pstmt.setString(2, plateNumber);

            int rowsUpdated = pstmt.executeUpdate();
            if (rowsUpdated > 0) {
                System.out.println("✅ Cập nhật giá thành công");
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }
}

package com.auction.database;

import java.sql.*;

/**
 * DAO = Data Access Object
 * 
 * File này chứa các hàm để query bảng users
 * Ví dụ: thêm user, tìm user, lấy tất cả users, v.v.
 */
public class UserDAO {

    // Thêm user mới
    public static void addUser(String username, String password, String email, 
                               String fullName, String userType, String phone, String address) {
        String sql = "INSERT INTO users (username, password, email, full_name, user_type, phone, address) " +
                     "VALUES (?, ?, ?, ?, ?, ?, ?)";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, username);
            pstmt.setString(2, password);
            pstmt.setString(3, email);
            pstmt.setString(4, fullName);
            pstmt.setString(5, userType);
            pstmt.setString(6, phone);
            pstmt.setString(7, address);

            pstmt.executeUpdate();
            System.out.println("✅ Thêm user '" + username + "' thành công");

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Tìm user theo username
    public static void findUserByUsername(String username) {
        String sql = "SELECT * FROM users WHERE username = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, username);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                System.out.println("\n Thông tin user:");
                System.out.println("  ID: " + rs.getInt("id"));
                System.out.println("  Username: " + rs.getString("username"));
                System.out.println("  Email: " + rs.getString("email"));
                System.out.println("  Tên: " + rs.getString("full_name"));
                System.out.println("  Loại: " + rs.getString("user_type"));
                System.out.println("  SĐT: " + rs.getString("phone") + "\n");
            } else {
                System.out.println("❌ Không tìm thấy user '" + username + "'");
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Lấy tất cả users
    public static void getAllUsers() {
        String sql = "SELECT id, username, email, full_name, user_type FROM users";

        try (Connection conn = DatabaseConnection.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            System.out.println("\n Danh sách users:");
            while (rs.next()) {
                System.out.println("  " + rs.getInt("id") + ". " + rs.getString("username") + 
                                 " (" + rs.getString("user_type") + ")");
            }
            System.out.println();

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Xóa user
    public static void deleteUser(String username) {
        String sql = "DELETE FROM users WHERE username = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, username);
            int rowsDeleted = pstmt.executeUpdate();

            if (rowsDeleted > 0) {
                System.out.println("✅ Xóa user '" + username + "' thành công");
            } else {
                System.out.println("❌ Không tìm thấy user '" + username + "'");
            }

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
        }
    }


    // Kiểm tra đăng nhập
    public static boolean checkLogin(String username, String password) {
        String sql = "SELECT * FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DatabaseConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, username);
            pstmt.setString(2, password);
            ResultSet rs = pstmt.executeQuery();

            return rs.next();  // True nếu tìm thấy, False nếu không

        } catch (SQLException e) {
            System.out.println("❌ Lỗi: " + e.getMessage());
            return false;
        }
    }
}

package com.auction.main;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class App extends Application {

    @Override
    public void start(Stage stage) throws Exception {
        FXMLLoader fxmlLoader = new FXMLLoader(getClass().getResource("/fxml/Login.fxml"));
        Parent root = fxmlLoader.load();

        Scene scene = new Scene(root, 1024, 720);
        stage.setTitle("Hệ Thống Đấu Giá Biển Số - VinGroup");
        stage.setScene(scene);
        stage.setResizable(false);
        stage.centerOnScreen();
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package com.auction.main;

import com.auction.database.DatabaseInitializer;
import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class App extends Application {

    @Override
    public void start(Stage stage) throws Exception {
        DatabaseInitializer.initDatabase();  // Khởi tạo database tự động

        FXMLLoader fxmlLoader = new FXMLLoader(getClass().getResource("/fxml/Login.fxml"));
        Parent root = fxmlLoader.load();

        Scene scene = new Scene(root, 1024, 720);
        stage.setTitle("Hệ Thống Đấu Giá Biển Số - VinGroup");
        stage.setScene(scene);
        stage.setResizable(false);
        stage.centerOnScreen();
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
